// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(address target, uint256 mintedAmount) public {
        vm.assume(target != address(0));
        vm.assume(mintedAmount <= type(uint256).max - c.balanceOf(target));
        uint256 supplyBefore = c.totalSupply();
        vm.prank(c.owner());
        c.mintToken(target, mintedAmount);
        assertTrue(c.totalSupply() == supplyBefore + mintedAmount);
    }
}
